    <div id="root"></div>

    <script>
      const e = (tag, props = {}, ...children) => ({ tag, props, children });
      const VOID_TAGS = new Set(["area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "source", "track", "wbr"]);

      function render(node) {
        if (node == null || node === false) return "";
        if (Array.isArray(node)) return node.map(render).join("");
        if (typeof node === "string" || typeof node === "number") {
          return String(node);
        }
        const { tag, props = {}, children = [] } = node;
        const attrs = Object.entries(props)
          .filter(([, value]) => value !== false && value != null)
          .map(([key, value]) => {
            if (key === "className") return ` class="${escapeHtml(value)}"`;
            if (key.startsWith("on")) return "";
            if (value === true) return ` ${key}`;
            return ` ${key}="${escapeHtml(value)}"`;
          })
          .join("");
        if (VOID_TAGS.has(tag)) {
          return `<${tag}${attrs}>`;
        }
        return `<${tag}${attrs}>${children.map(render).join("")}</${tag}>`;
      }

      function escapeHtml(value) {
        return String(value)
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#39;");
      }

      function validate(values) {
        const errors = {};
        if (!values.fullName.trim()) {
          errors.fullName = "Full name is required.";
        }
        if (!values.email.trim()) {
          errors.email = "Email address is required.";
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) {
          errors.email = "Enter a valid email address.";
        }
        if (values.phone.trim() && !/^\+?[0-9\s().-]{7,}$/.test(values.phone.trim())) {
          errors.phone = "Enter a valid phone number or leave it blank.";
        }
        return errors;
      }

      function field({ id, label, type, name, placeholder, value, helper, error, required }) {
        const describedBy = [helper ? `${id}-help` : null, error ? `${id}-error` : null].filter(Boolean).join(" ");
        return e(
          "div",
          { className: "form-field" },
          e("label", { for: id }, label),
          e("input", {
            id,
            name,
            type,
            value,
            placeholder,
            required: required ? true : null,
            "aria-invalid": error ? "true" : "false",
            "aria-describedby": describedBy || null
          }),
          helper ? e("p", { className: "helper", id: `${id}-help` }, helper) : null,
          error ? e("p", { className: "error", id: `${id}-error`, role: "alert" }, error) : null
        );
      }

      function ContactForm() {
        const state = {
          values: { fullName: "", email: "", phone: "" },
          errors: {},
          submitted: false
        };

        const root = document.getElementById("root");

        function sync() {
          root.innerHTML = render(
            e(
              "main",
              { className: "page" },
              e(
