                      label: "Full name",
                      type: "text",
                      name: "fullName",
                      placeholder: "Jordan Lee",
                      value: state.values.fullName,
                      error: state.errors.fullName,
                      required: true
                    }),
                    field({
                      id: "email",
                      label: "Email address",
                      type: "email",
                      name: "email",
                      placeholder: "jordan@example.com",
                      value: state.values.email,
                      error: state.errors.email,
                      required: true
                    }),
                    field({
                      id: "phone",
                      label: "Phone number",
                      type: "tel",
                      name: "phone",
                      placeholder: "+1 (555) 123-4567",
                      value: state.values.phone,
                      helper: "Optional. Use a format like +1 (555) 123-4567 or 555-123-4567.",
                      error: state.errors.phone,
                      required: false
                    }),
                    e(
                      "div",
                      { className: "actions" },
                      e("button", { type: "submit" }, "Submit")
                    )
                  )
                )
              )
            )
          );

          const form = document.getElementById("contact-form");
          form.addEventListener("submit", onSubmit);
          form.fullName.addEventListener("input", onInput);
          form.email.addEventListener("input", onInput);
          form.phone.addEventListener("input", onInput);
        }

        function onInput(event) {
          const { name, value } = event.target;
          state.values[name] = value;
          state.errors = validate(state.values);
          sync();
        }

        function onSubmit(event) {
          event.preventDefault();
          state.errors = validate(state.values);
          state.submitted = Object.keys(state.errors).length === 0;
          sync();
        }

        sync();
      }

